(function () {
  "use strict";

  var VERSION = "20260724-compat2";

  function loadCompatibilityStyles() {
    if (document.querySelector('link[data-terraz-compat="true"]')) {
      return;
    }

    var link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "assets/css/visual-refinements.css?v=" + VERSION;
    link.dataset.terrazCompat = "true";
    document.head.appendChild(link);
  }

  function prepareLegacyVideo() {
    if (document.getElementById("hero-video")) {
      return;
    }

    var container = document.querySelector(".bg-video");
    if (!container) {
      return;
    }

    container.id = "hero-video";
    container.classList.add("hero__video");
  }

  function replaceLegacyCopyControl() {
    if (document.getElementById("server-copy")) {
      return;
    }

    var address = document.querySelector("url");
    var legacyControl = address ? address.closest("mark") : null;
    if (!address || !legacyControl || !legacyControl.parentNode) {
      return;
    }

    var button = document.createElement("button");
    button.className = "server-copy";
    button.id = "server-copy";
    button.type = "button";
    button.dataset.address = address.textContent.trim() || "S.TERRAZ.RU:7777";
    button.setAttribute("aria-describedby", "copy-status");

    var addressLabel = document.createElement("span");
    addressLabel.className = "server-copy__address";
    addressLabel.textContent = button.dataset.address;

    var action = document.createElement("span");
    action.className = "server-copy__action";

    var icon = document.createElement("span");
    icon.className = "server-copy__icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = "⧉";

    var label = document.createElement("span");
    label.className = "server-copy__label";
    label.textContent = "Копировать";

    action.append(icon, label);
    button.append(addressLabel, action);

    var status = document.createElement("span");
    status.className = "copy-status";
    status.id = "copy-status";
    status.setAttribute("role", "status");
    status.setAttribute("aria-live", "polite");
    status.setAttribute("aria-atomic", "true");
    status.textContent = "Скопировано";

    legacyControl.replaceWith(button);
    button.insertAdjacentElement("afterend", status);

    var parent = button.parentElement;
    if (parent) {
      parent.classList.add("legacy-server-actions");
    }
  }

  function iconClassForLink(link) {
    var href = link.getAttribute("href") || "";
    if (href.indexOf("vk.com") !== -1) return "social-link__icon--vk";
    if (href.indexOf("youtube.com") !== -1) return "social-link__icon--youtube";
    if (href === "/conference" || href.indexOf("conference") !== -1) return "social-link__icon--discord";
    if (href.indexOf("t.me") !== -1) return "social-link__icon--telegram";
    if (href.indexOf("twitch.tv") !== -1) return "social-link__icon--twitch";
    return "";
  }

  function restoreLegacySocialIcons() {
    var links = Array.prototype.slice.call(document.querySelectorAll(
      'a[href*="vk.com"], a[href*="youtube.com"], a[href="/conference"], a[href*="t.me"], a[href*="twitch.tv"]'
    ));

    links = links.filter(function (link) {
      return link.closest(".container-mid") && !link.closest(".portal-link");
    });

    if (!links.length) {
      return;
    }

    var parent = links[0].parentElement;
    if (parent) {
      parent.classList.add("social-links", "legacy-social-links");
    }

    links.forEach(function (link) {
      var iconClass = iconClassForLink(link);
      if (!iconClass) {
        return;
      }

      link.removeAttribute("style");
      link.classList.add("social-link");
      link.replaceChildren();

      var icon = document.createElement("span");
      icon.className = "social-link__icon " + iconClass;
      icon.setAttribute("aria-hidden", "true");
      link.appendChild(icon);
    });
  }

  loadCompatibilityStyles();
  prepareLegacyVideo();
  replaceLegacyCopyControl();
  restoreLegacySocialIcons();
}());
